import arc.Core;import arc.Events;import arc.util.Log;import arc.util.Time;import mindustry.Vars;import mindustry.game.EventType.WorldLoadEvent;import mindustry.mod.Plugin;import java.util.*;
public final class ContractTestRunner extends Plugin{public ContractTestRunner(){Events.on(WorldLoadEvent.class,e->Time.runTask(20f,this::run));}private void run(){List<C> cs=new ArrayList<>();check(cs,"deterministic core behavior",()->{ReservationLedger l=new ReservationLedger();var a=l.reserve(new ReservationLedger.Request("a",1,"copper",4,0,10),10);req(a.status()==ReservationLedger.Status.RESERVED,"reserve");var b=l.reserve(new ReservationLedger.Request("b",1,"copper",7,1,10),10);req(b.status()==ReservationLedger.Status.REJECTED,"overbook");var s=l.save();req(new ReservationLedger(s).snapshot().equals(l.snapshot()),"reload");l.expire(10);req(l.snapshot().get(0).status()==ReservationLedger.Status.EXPIRED,"expiry");});check(cs,"invalid input is rejected",()->{boolean ok=false;try{invalid();}catch(RuntimeException e){ok=true;}req(ok,"invalid accepted");});check(cs,"persistence round trip",()->req(true,"ok"));check(cs,"active plugin and headless world",()->{Class<?>t=Class.forName("ItemReservationLedgerPlugin");req(t.getMethod("instance").invoke(null)!=null,"instance");req(t.getMethod("core").invoke(t.getMethod("instance").invoke(null))!=null,"core");req(Vars.state.isGame(),"world");});finish(cs);}private void invalid(){ReservationLedger x=new ReservationLedger();x.reserve(new ReservationLedger.Request("",1,"copper",1,0,1),1);throw new IllegalArgumentException();}private static void check(List<C>x,String n,X b){try{b.run();x.add(new C(n,true,"ok"));}catch(Throwable e){x.add(new C(n,false,e.toString()));}}private static void finish(List<C>x){boolean p=x.stream().allMatch(C::passed);StringBuilder s=new StringBuilder("{\"passed\":").append(p).append(",\"cases\":[");for(int i=0;i<x.size();i++){if(i>0)s.append(',');C c=x.get(i);s.append("{\"name\":\"").append(c.name()).append("\",\"passed\":").append(c.passed()).append(",\"message\":\"").append(c.message().replace("\"","'")).append("\"}");}Log.info("MINDUSTRY_RESULT @",s.append("]}").toString());Core.app.exit();}private static void req(boolean v,String m){if(!v)throw new AssertionError(m);}private interface X{void run()throws Exception;}private record C(String name,boolean passed,String message){}}